// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }

    function testFuzz_property(uint256 creatorAmt, uint256 otherAmt, address to) public {
        vm.assume(creatorAmt <= VALUE_CAP);
        vm.assume(otherAmt <= VALUE_CAP);
        vm.assume(to != address(0) && to != address(c) && to != address(this));
        vm.assume(to.code.length == 0); // plain recipient so transfer cannot fail
        creatorAmt = bound(creatorAmt, 1, 1e24);
        otherAmt = bound(otherAmt, 1, 1e24);

        // creator (this test contract, the deployer) deposits
        vm.deal(address(this), creatorAmt);
        c.deposit{value: creatorAmt}();

        // a second, non-creator depositor adds Ether the mutant would strand
        vm.deal(to, otherAmt);
        vm.prank(to);
        c.deposit{value: otherAmt}();

        bool ok;
        vm.prank(address(this)); // creator
        try c.migrateTo(to) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a successful migration drains the whole contract balance.
        assertTrue(!ok || address(c).balance == 0);
    }
}
